package dev.ryanhcode.sable.api.sublevel; import net.minecraft.world.level.Level; import dev.ryanhcode.sable.sublevel.SubLevel; public class SubLevelContainer { public static SubLevelContainer value; public SubLevel sub; public int x,z; public static SubLevelContainer getContainer(Level l){return value;} public boolean inBounds(int x,int z){return x==this.x&&z==this.z;} public Plot getPlot(int x,int z){return inBounds(x,z)?new Plot(sub):null;} public record Plot(SubLevel getSubLevel) {public SubLevel getSubLevel(){return getSubLevel;}} }
